  if os.name=='nt':flags+=['--plugin-dir='+str(base/'lib/plugin')]
  with process(flags+['--initialize-insecure','--skip-networking'],root,'initialize') as p:
   p.wait(timeout=30)
   assert p.returncode==0,(root/'initialize.log').read_text(errors='replace')[-2500:]
  with socket.socket() as s:s.bind(('127.0.0.1',0));port=s.getsockname()[1]
  try:
   with process(flags+['--bind-address=127.0.0.1','--port='+str(port),'--socket='+str(root/'mysql.sock'),'--pid-file='+str(root/'mysql.pid'),'--max-execution-time=1200'],root,'server') as p:
    rootconn=None
    try:
     deadline=time.monotonic()+12
     while rootconn is None:
      try:rootconn=pymysql.connect(host='127.0.0.1',port=port,user='root',charset='utf8mb4',autocommit=True,connect_timeout=1,read_timeout=3,write_timeout=3,local_infile=False)
      except pymysql.Error:
       assert p.poll() is None and time.monotonic()<deadline,(root/'server.log').read_text(errors='replace')[-2500:]
       time.sleep(.1)
     assert int((root/'mysql.pid').read_text().strip())==p.pid,'server escaped monitored PID'
     execute(rootconn,"CREATE DATABASE training CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci")
     execute(rootconn,'USE training')
     secret=secrets.token_hex(24)
     execute(rootconn,"CREATE USER 'student'@'127.0.0.1' IDENTIFIED BY %s",(secret,))
     def learner(privileges):
      execute(rootconn,"GRANT "+privileges+" ON training.* TO 'student'@'127.0.0.1'")
      return pymysql.connect(host='127.0.0.1',port=port,user='student',password=secret,database='training',charset='utf8mb4',autocommit=True,connect_timeout=2,read_timeout=3,write_timeout=3,local_infile=False)
     yield rootconn,learner
    finally:
     if rootconn:
      try:execute(rootconn,'SHUTDOWN')
      except pymysql.Error:pass
      rootconn.close()
     try:p.wait(timeout=5)
     except subprocess.TimeoutExpired:pass
  finally:
   with socket.socket() as s:assert s.connect_ex(('127.0.0.1',port))!=0,'owned MySQL port remained open'

